import React, { useState } from "react";
import NetworkBackground from "../components/NetworkBackground";
import { MagnifyingGlassIcon } from "@heroicons/react/24/outline";

// --- Data arrays (keep these as they are) ---
const expertiseTabs = [
  "Software Engineering",
  "Product Management",
  "Data Science",
  "Marketing",
  "Design",
];

const mentorProfiles = [
    { name: "Fatima Khan", role: "Software Engineering", image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80" },
    { name: "Benjamin Hayes", role: "Product Management", image: "https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=300&q=80" },
    { name: "Aisha Rahman", role: "Data Science", image: "https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=300&q=80" },
    { name: "Samuel Reed", role: "Marketing", image: "https://images.unsplash.com/photo-1552053566-35c9e1e96c79?w=300&q=80" },
    { name: "Zainab Malik", role: "Design", image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80" },
    { name: "Elijah Bennett", role: "Software Engineering", image: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=300&q=80" },
    { name: "Nadia Ali", role: "Product Management", image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80" },
    { name: "Grayson Cole", role: "Data Science", image: "https://images.unsplash.com/photo-1552053566-35c9e1e96c79?w=300&q=80" },
    { name: "Aaliyah Siddiqui", role: "Marketing", image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80" },
    { name: "Jackson Reed", role: "Design", image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80" },
    { name: "Hafsa Ahmed", role: "Software Engineering", image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80" },
    { name: "Carter Hayes", role: "Product Management", image: "https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=300&q=80" },
    { name: "Mariam Hassan", role: "Data Science", image: "https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=300&q=80" },
    { name: "Henry Cole", role: "Marketing", image: "https://images.unsplash.com/photo-1552053566-35c9e1e96c79?w=300&q=80" },
    { name: "Lina Ibrahim", role: "Design", image: "https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=300&q=80" },
];


export default function MentorPage() {
  const [search, setSearch] = useState("");
  const [activeExpertise, setActiveExpertise] = useState("Software Engineering");

  const filteredProfiles = mentorProfiles.filter((m) => {
    const text = (m.name + " " + m.role).toLowerCase();
    const q = search.toLowerCase();
    const matchesSearch = !q || text.includes(q);
    const matchesExpertise = activeExpertise ? m.role === activeExpertise : true;
    return matchesSearch && matchesExpertise;
  });

  return (
    <div className="relative min-h-screen bg-white">
      <NetworkBackground />

      <main className="relative z-10 max-w-5xl mx-auto px-4 pt-10 pb-24 xl:px-0">
        
        {/* Mentors avatar grid card */}
        <section className="mb-16">
          <div className="bg-white/95 rounded-3xl shadow-lg border border-gray-100 px-6 sm:px-8 pt-8 pb-10">
            {/* Search Bar with Icon */}
            <div className="relative w-full mb-6">
                <MagnifyingGlassIcon className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                <input
                    type="text"
                    placeholder="Search mentors by name or expertise"
                    className="w-full rounded-full border border-gray-200 bg-gray-50 pl-11 pr-4 py-2.5 text-sm outline-none focus:ring-2 focus:ring-emerald-300"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                />
            </div>

            {/* Expertise Tabs - Horizontally scrollable */}
            <div className="flex space-x-2 mb-8 overflow-x-auto pb-2">
              {expertiseTabs.map((tab) => (
                <button
                  key={tab}
                  onClick={() => setActiveExpertise(tab)}
                  className={`flex-shrink-0 px-4 py-1.5 rounded-lg text-xs font-semibold border transition-colors ${
                    activeExpertise === tab
                      ? "bg-emerald-500 text-white border-emerald-500"
                      : "bg-white text-gray-600 border-gray-200 hover:bg-gray-100"
                  }`}
                >
                  {tab}
                </button>
              ))}
            </div>

            {/* Mentor Avatars */}
            <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-x-6 gap-y-8 mb-8">
              {filteredProfiles.map((m) => (
                <div key={m.name} className="flex flex-col items-center text-center">
                  <div className="w-24 h-24 rounded-full overflow-hidden mb-2 border-2 border-gray-100 shadow-md">
                    <img src={m.image} alt={m.name} className="w-full h-full object-cover" />
                  </div>
                  <div className="text-sm font-semibold text-gray-800">{m.name}</div>
                  <div className="text-xs text-gray-500">{m.role}</div>
                </div>
              ))}
            </div>

            {/* Bottom Buttons */}
            <div className="flex flex-col sm:flex-row justify-center items-center gap-4 mt-4">
              <button className="px-6 py-2 rounded-full bg-emerald-500 text-white text-sm font-semibold hover:bg-emerald-600 shadow-sm">
                Request Mentorship
              </button>
              <button className="px-6 py-2 rounded-full bg-gray-100 text-gray-800 text-sm font-semibold border border-gray-200 hover:bg-gray-200">
                View Profile
              </button>
            </div>
          </div>
        </section>

        {/* For Mentorship bottom card */}
        <section>
          <div className="bg-white/95 rounded-3xl shadow-lg border border-gray-100 px-6 sm:px-10 py-10 flex flex-col md:flex-row gap-8 items-center">
            <div className="md:w-1/2 flex justify-center">
              <div className="rounded-2xl overflow-hidden bg-gray-100 max-w-sm w-full shadow-md">
                <img src="https://images.unsplash.com/photo-1544723795-3fb6469f5b39?w=500&q=80" alt="A smiling mentor at a desk" className="w-full h-full object-cover" />
              </div>
            </div>
            <div className="md:w-1/2 w-full">
              <h2 className="text-2xl font-bold mb-2 text-gray-800">For Mentorship</h2>
              <p className="text-sm text-gray-600 mb-6">
                Get questions about the Landing Page UI Kit? Our team is here to help. Contact us for quick and friendly support.
              </p>
              <div className="space-y-4">
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">👤</span>
                  <input type="text" placeholder="Full Name" className="w-full h-12 rounded-full border border-gray-200 pl-11 pr-4 text-sm outline-none focus:ring-2 focus:ring-emerald-300" />
                </div>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400">✉️</span>
                  <input type="email" placeholder="Email" className="w-full h-12 rounded-full border border-gray-200 pl-11 pr-4 text-sm outline-none focus:ring-2 focus:ring-emerald-300" />
                </div>
                <button className="w-full mt-2 px-6 py-3 rounded-full bg-emerald-500 text-white font-semibold hover:bg-emerald-600 shadow-md">
                  Get Started
                </button>
              </div>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}
